 void load(Uri uri){int id=++gen;status.setText("ZIP 목록 읽는 중…");pool.execute(()->{ParcelFileDescriptor p=null;FileInputStream f=null;ZipFile z=null;try{p=getContentResolver().openFileDescriptor(uri,"r");if(p==null)throw new IOException("접근 불가");f=new FileInputStream(p.getFileDescriptor());z=ZipFile.builder().setSeekableByteChannel(f.getChannel()).get();ArrayList<ZipArchiveEntry> entries=new ArrayList<>();Enumeration<ZipArchiveEntry> it=z.getEntries();while(it.hasMoreElements()){ZipArchiveEntry e=it.nextElement();if(!e.isDirectory()&&media(e))entries.add(e);}entries.sort((a,b)->a.getName().compareToIgnoreCase(b.getName()));ParcelFileDescriptor rp=p;FileInputStream rf=f;ZipFile rz=z;ui.post(()->{if(id!=gen){close(rz);close(rf);close(rp);return;}closeZip();pfd=rp;fis=rf;channel=rf.getChannel();zip=rz;all.clear();all.addAll(entries);TreeSet<String> folders=new TreeSet<>();for(ZipArchiveEntry entry:entries){String name=entry.getName();int slash=name.lastIndexOf('/');if(slash>0)folders.add(name.substring(0,slash));}ArrayList<String> options=new ArrayList<>();options.add("전체 폴더");options.addAll(folders);selectedFolder="전체 폴더";folderPicker.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,options));folderPicker.setSelection(0);synchronized(cache){cache.clear();}pending.clear();filter();});}catch(Exception ex){close(z);close(f);close(p);ui.post(()->{if(id==gen)status.setText("ZIP 열기 실패: "+ex.getMessage());});}});}
